///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_doSave
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_doSave = async function () {
    const sbmOptions = {
        id: "tx_doSave",
        method: "post",
        action: "/upload/uploadFile.do",
        ref: "dma_doSaveReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldbnf35023.tx_doSave" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.mpd_files_selectCallback
 * @author Inswave
 * @date 2026. 09. 29
 * @param data
 * @returns
 * @hidden N
*/
scwin.mpd_files_selectCallback = function (data) { const d = $c.util.getComponent('dlt_files'); if (!d) { return; } const rows = []; for (let i = 0; i < (data || []).length; i++) { rows.push({ FILE_NM: data[i].name, FILE_SIZE: String(data[i].size), CHK: '' }); } if (rows.length) { d.insertJSON(d.getRowCount(), rows); } };

/**
 * @method
 * @name scwin.setParamFromParent
 * @author Inswave
 * @date 2026. 09. 29
 * @param arr
 * @returns
 * @hidden N
*/
scwin.setParamFromParent = function (arr) {
    /* sdd-asis-lifecycle:begin setParamFromParent — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    for (let i = 0; i < arr.length; i++) {
        $("#inputContainer").append("<input type='hidden' name='bnd_appl_id_list' value='" + arr[i] + "'>");
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.doSave
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.doSave = async function () {
    /* sdd-asis-lifecycle:begin doSave — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const fm = (document.SendForm || { elements: [] });
    if (rownum < 1) {
        await $c.win.alert("업로드 할 대상이 없습니다.");
        return;
    }
    const fileYn = 'N';
    if (rownum > 0) {
        for (let i = 0; i < rownum; i++) {
            let temp;
            if (rownum == 1) {
                temp = fm.attach_file_tp_cd.value;
            } else {
                temp = fm.attach_file_tp_cd[i].value;
            }
            if ($("input[name='attach_file_nm[" + i + "]']").val() === "") {
                await $c.win.alert("파일을 선택하십시오.");
                console.error("[sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_focus — {target}.focus({args}) */
                return;
            }
            if (temp === "") {
                await $c.win.alert("첨부된 파일의 구분을 선택하십시오.");
                console.error("[sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_focus — {target}.focus({args}) */
                return;
            }
        }
    }
    const totFileSize = (Math.round(((($c.util.getComponent('dlt_files')) && ($c.util.getComponent('dlt_files')).getRowCount) ? Array.from({ length: ($c.util.getComponent('dlt_files')).getRowCount() }, function (x, i) { return Number(($c.util.getComponent('dlt_files')).getCellData(i, 'FILE_SIZE')) || 0; }).reduce(function (a, b) { return a + b; }, 0) : 0) / (1024 * 1024) * 100) / 100);
    if (totFileSize > 100) {
        await $c.win.alert("전체 첨부파일의 크기는 최대 100MB까지 허용됩니다.\n현재 크기 = " + totFileSize + "MB");
        return false;
    }
    if (!await $c.win.confirm("업로드하시겠습니까?")) {
        return;
    }
    $c.util.getComponent('txt_spanUpload').setLabel("업로드 중...");
    $("#aLinkUpload").attr("onclick", "return false;");
    fm.action = '/upload/uploadFile.do';
    $c.util.getComponent('dma_doSaveReq').set('method', 'saveUploadFile');
    await scwin.tx_doSave();
    /* sdd-asis-lifecycle:end */
};
